-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-dispute-decision-rpc.sql
-- Source SHA256: F7A2A11C98733115A8560E90EE736CFA8DB388FDB9462EB8EB6C8784F51A5220
-- Local replay required before any staging promotion.
create or replace function finance_private.current_dispute_decision_worker_is_trusted() returns boolean language sql stable security definer set search_path=pg_catalog as $$select false$$;
create or replace function finance_private.current_actor_can_decide_dispute(p_actor_id uuid,p_dispute_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$select false$$;
create or replace function finance_private.resolve_dispute_decision_context(p_dispute_id uuid,p_decision_date date,p_accepted_amount numeric) returns jsonb language sql stable security definer set search_path=pg_catalog as $$select null::jsonb$$;

create or replace function finance_api.commit_dispute_decision(p_actor_id uuid,p_dispute_id uuid,p_decision text,p_accepted_amount numeric,p_decision_date date,p_expected_version bigint,p_reason_code text,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare d finance.disputes%rowtype;o finance.open_items%rowtype;a finance.accruals%rowtype;c jsonb;ar finance.approval_requests%rowtype;v_period uuid;v_journal uuid;v_accrual uuid;v_credit uuid;v_seq integer;v_net numeric;v_tax numeric;v_gross numeric;v_result jsonb;
begin
 if not finance_private.current_dispute_decision_worker_is_trusted() or not finance_private.current_actor_can_decide_dispute(p_actor_id,p_dispute_id) then raise exception using errcode='42501',message='trusted dispute decision authorization required';end if;
 if p_decision not in ('ACCEPTED','PARTIALLY_ACCEPTED','REJECTED') or p_expected_version<1 or pg_catalog.btrim(coalesce(p_reason_code,''))='' or pg_catalog.btrim(coalesce(p_idempotency_key,''))='' or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid dispute decision command';end if;
 select * into d from finance.disputes where id=p_dispute_id for update;if not found then raise exception using errcode='P0002',message='dispute not found';end if;
 if d.decision_idempotency_key is not null then if d.decision_idempotency_key=p_idempotency_key and d.decision_intent_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','disputeId',d.id,'status',d.status,'version',d.version,'correctionResourceIds',case when d.decision_journal_entry_id is null then '[]'::jsonb else pg_catalog.jsonb_build_array(d.decision_journal_entry_id,(select id from finance.accruals where journal_entry_id=d.decision_journal_entry_id limit 1),(select id from finance.open_items where accrual_id=(select id from finance.accruals where journal_entry_id=d.decision_journal_entry_id limit 1) limit 1)) end);else return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;end if;
 if d.version<>p_expected_version or d.status not in ('SUBMITTED','UNDER_REVIEW') then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if (p_decision='ACCEPTED' and p_accepted_amount<>d.disputed_amount) or (p_decision='PARTIALLY_ACCEPTED' and not(p_accepted_amount>0 and p_accepted_amount<d.disputed_amount)) or (p_decision='REJECTED' and p_accepted_amount<>0) then raise exception using errcode='23514',message='decision amount does not match status';end if;
 select * into o from finance.open_items where id=d.open_item_id and legal_entity_id=d.legal_entity_id for update;select * into a from finance.accruals where id=o.accrual_id and dealer_account_id=o.dealer_account_id and branch_id=o.branch_id;
 if p_accepted_amount+(select coalesce(pg_catalog.sum(x.accepted_amount),0) from finance.disputes x where x.open_item_id=o.id and x.id<>d.id and x.status in ('ACCEPTED','PARTIALLY_ACCEPTED','CLOSED'))>o.original_amount then raise exception using errcode='23514',message='cumulative accepted dispute amount exceeds original open item';end if;
 select * into ar from finance.approval_requests where legal_entity_id=d.legal_entity_id and subject_type='DISPUTE_DECISION' and subject_id=d.id and status='APPROVED' order by created_at_utc desc limit 1;
 if ar.id is null or ar.prepared_by=p_actor_id or not exists(select 1 from finance.approval_steps s where s.approval_request_id=ar.id and s.decision='APPROVE' and s.decided_by<>ar.prepared_by and s.evidence_ref is not null) or exists(select 1 from finance.approval_steps s where s.approval_request_id=ar.id and s.decision is distinct from 'APPROVE') then raise exception using errcode='23514',message='approved maker checker evidence required';end if;
 if p_decision<>'REJECTED' then
  c:=finance_private.resolve_dispute_decision_context(d.id,p_decision_date,p_accepted_amount);if c is null or (c->>'scopeValid')::boolean is distinct from true then raise exception using errcode='23514',message='approved dispute correction context required';end if;
  v_period:=(c->>'financePeriodId')::uuid;v_net:=(c->>'netAmount')::numeric;v_tax:=(c->>'taxAmount')::numeric;v_gross:=(c->>'grossAmount')::numeric;
  if v_net<0 or v_tax<0 or v_gross<>v_net+v_tax or v_gross<>p_accepted_amount or pg_catalog.btrim(coalesce(c->>'netDebitAccountCode',''))='' or pg_catalog.btrim(coalesce(c->>'receivableCreditAccountCode',''))='' or (v_tax>0 and pg_catalog.btrim(coalesce(c->>'taxDebitAccountCode',''))='') then raise exception using errcode='23514',message='correction breakdown mismatch';end if;
  if not exists(select 1 from finance.finance_periods fp where fp.id=v_period and fp.legal_entity_id=d.legal_entity_id and fp.mode='LIVE' and fp.status='OPEN' and p_decision_date between fp.period_start and fp.period_end) then raise exception using errcode='23514',message='open live posting period required';end if;
  insert into finance.journal_entries(legal_entity_id,finance_period_id,idempotency_key,intent_hash,entry_type,business_date,posting_date,status,posted_at_utc,posted_by,created_by,correlation_id) values(d.legal_entity_id,v_period,p_idempotency_key,p_intent_hash,'DISPUTE_CORRECTION',p_decision_date,p_decision_date,'POSTED',pg_catalog.clock_timestamp(),p_actor_id,p_actor_id,p_correlation_id) returning id into v_journal;
  insert into finance.journal_lines(journal_entry_id,line_no,dealer_account_id,account_code,branch_id,currency_code,debit_amount,credit_amount,dimensions,created_by,correlation_id) values(v_journal,1,o.dealer_account_id,c->>'netDebitAccountCode',o.branch_id,o.currency_code,v_net,0,pg_catalog.jsonb_build_object('disputeId',d.id,'originalAccrualId',a.id,'originalFinancePeriodId',c->>'originalFinancePeriodId'),p_actor_id,p_correlation_id);
  if v_tax>0 then insert into finance.journal_lines(journal_entry_id,line_no,dealer_account_id,account_code,branch_id,currency_code,debit_amount,credit_amount,dimensions,created_by,correlation_id) values(v_journal,2,o.dealer_account_id,c->>'taxDebitAccountCode',o.branch_id,o.currency_code,v_tax,0,pg_catalog.jsonb_build_object('disputeId',d.id),p_actor_id,p_correlation_id);end if;
  insert into finance.journal_lines(journal_entry_id,line_no,dealer_account_id,account_code,branch_id,currency_code,debit_amount,credit_amount,dimensions,created_by,correlation_id) values(v_journal,case when v_tax>0 then 3 else 2 end,o.dealer_account_id,c->>'receivableCreditAccountCode',o.branch_id,o.currency_code,0,v_gross,pg_catalog.jsonb_build_object('disputeId',d.id,'originalOpenItemId',o.id),p_actor_id,p_correlation_id);
  select coalesce(pg_catalog.max(sequence_no),0)+1 into v_seq from finance.accruals where (calculation_run_id is not distinct from a.calculation_run_id) and (pass_through_expense_id is not distinct from a.pass_through_expense_id);
  insert into finance.accruals(legal_entity_id,calculation_run_id,pass_through_expense_id,dealer_account_id,branch_id,journal_entry_id,sequence_no,fee_definition_id,currency_code,net_amount,tax_amount,gross_amount,status,reversal_of_id,created_by,correlation_id) values(d.legal_entity_id,a.calculation_run_id,a.pass_through_expense_id,o.dealer_account_id,o.branch_id,v_journal,v_seq,a.fee_definition_id,o.currency_code,-v_net,-v_tax,-v_gross,'POSTED',a.id,p_actor_id,p_correlation_id) returning id into v_accrual;
  insert into finance.open_items(legal_entity_id,accrual_id,dealer_account_id,branch_id,due_date,currency_code,item_type,original_amount,allocated_amount,open_amount,status,created_by,correlation_id) values(d.legal_entity_id,v_accrual,o.dealer_account_id,o.branch_id,p_decision_date,o.currency_code,'CREDIT',v_gross,0,v_gross,'OPEN',p_actor_id,p_correlation_id) returning id into v_credit;
 end if;
 update finance.disputes set accepted_amount=p_accepted_amount,status=p_decision,decision_idempotency_key=p_idempotency_key,decision_intent_hash=p_intent_hash,decision_reason_code=p_reason_code,decision_note_hash=p_note_hash,decision_journal_entry_id=v_journal,decided_by=p_actor_id,decided_at_utc=pg_catalog.clock_timestamp(),version=version+1,correlation_id=p_correlation_id where id=d.id;
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(d.legal_entity_id,'finance.dispute','finance.dispute.decided','DISPUTE',d.id,d.version+1,pg_catalog.jsonb_build_object('disputeId',d.id,'decision',p_decision,'correctionJournalEntryId',v_journal),p_intent_hash,'PENDING',p_correlation_id);
 insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,before_hash,after_hash,integrity_hash,safe_context,correlation_id) values(d.legal_entity_id,p_actor_id,'USER','DISPUTE_DECIDED','DISPUTE',d.id,p_decision,p_reason_code,null,p_intent_hash,pg_catalog.md5(d.id::text||p_intent_hash||p_correlation_id::text),pg_catalog.jsonb_build_object('approvalRequestId',ar.id,'noteHash',p_note_hash),p_correlation_id);
 v_result:=pg_catalog.jsonb_build_object('outcome','COMMITTED','disputeId',d.id,'status',p_decision,'version',d.version+1,'correctionResourceIds',case when v_journal is null then '[]'::jsonb else pg_catalog.jsonb_build_array(v_journal,v_accrual,v_credit) end);return v_result;
end$$;
revoke all on function finance_api.commit_dispute_decision(uuid,uuid,text,numeric,date,bigint,text,text,text,text,uuid) from public,anon,authenticated;
